31	type PersistedState struct {
32		InFlightProposal *InFlightData
33		Entries          [][]byte
34		Logger           api.Logger
35		WAL              api.WriteAheadLog
36	}
37	
38	func (ps *PersistedState) Save(msgToSave *protos.SavedMessage) error {
39		if proposed := msgToSave.GetProposedRecord(); proposed != nil {
40			ps.storeProposal(proposed)
41		}
42		if prepared := msgToSave.GetCommit(); prepared != nil {
43			ps.storePrepared(prepared)
44		}
45	
46		b, err := proto.Marshal(msgToSave)
47		if err != nil {
48			ps.Logger.Panicf("Failed marshaling message: %v", err)
49		}
50		// It is only safe to truncate if we either:
51		//
52		// 1) Process a pre-prepare, because it means we safely persisted the
53		// previous proposal and have a stable checkpoint.
54		// 2) Acquired a new view message which contains 2f+1 attestations
55		//    of the cluster agreeing to a new view configuration.
56		newProposal := msgToSave.GetProposedRecord() != nil
57		// TODO: handle view message here as well, and add "|| finalizedView" to truncate flag
58		return ps.WAL.Append(b, newProposal)
59	}
