113	func (vs *voteSet) clear(n uint64) {
114		// Drain the votes channel
115		for len(vs.votes) > 0 {
116			<-vs.votes
117		}
118	
119		vs.voted = make(map[uint64]struct{}, n)
120		vs.votes = make(chan *vote, n)
121	}
122	
123	func (vs *voteSet) registerVote(voter uint64, message *protos.Message) {
124		if !vs.validVote(voter, message) {
125			return
126		}
127	
128		_, hasVoted := vs.voted[voter]
129		if hasVoted {
130			// Received double vote
131			return
132		}
133	
134		vs.voted[voter] = struct{}{}
135		vs.votes <- &vote{Message: message, sender: voter}
136	}
