272	// NewProposer returns a new view
273	func (pm *ProposalMaker) NewProposer(leader, proposalSequence, viewNum, decisionsInView uint64, quorumSize int) (proposer Proposer, phase Phase) {
274		view := &View{
275			RetrieveCheckpoint: pm.Checkpoint.Get,
276			DecisionsPerLeader: pm.DecisionsPerLeader,
277			N:                  pm.N,
278			NodesList:          pm.NodesList,
279			LeaderID:           leader,
280			SelfID:             pm.SelfID,
281			Quorum:             quorumSize,
282			Number:             viewNum,
283			Decider:            pm.Decider,
284			FailureDetector:    pm.FailureDetector,
285			Sync:               pm.Sync,
286			Logger:             pm.Logger,
287			Comm:               pm.Comm,
288			Verifier:           pm.Verifier,
289			Signer:             pm.Signer,
290			MembershipNotifier: pm.MembershipNotifier,
291			ProposalSequence:   proposalSequence,
292			DecisionsInView:    decisionsInView,
293			State:              pm.State,
294			InMsgQSize:         pm.InMsqQSize,
295			ViewSequences:      pm.ViewSequences,
296			MetricsBlacklist:   pm.MetricsBlacklist,
297			MetricsView:        pm.MetricsView,
298		}
299	
300		view.ViewSequences.Store(ViewSequence{
301			ViewActive:  true,
302			ProposalSeq: proposalSequence,
303		})
304	
305		pm.restoreOnceFromWAL.Do(func() {
306			err := pm.State.Restore(view)
307			if err != nil {
308				pm.Logger.Panicf("Failed restoring view from WAL: %v", err)
309			}
310		})
311	
312		if proposalSequence > view.ProposalSequence {
313			view.ProposalSequence = proposalSequence
314			view.DecisionsInView = decisionsInView
315		}
316	
317		if viewNum > view.Number {
318			view.Number = viewNum
319			view.DecisionsInView = decisionsInView
320		}
321	
322		view.MetricsView.ViewNumber.Set(float64(view.Number))
323		view.MetricsView.LeaderID.Set(float64(view.LeaderID))
324		view.MetricsView.ProposalSequence.Set(float64(view.ProposalSequence))
325		view.MetricsView.DecisionsInView.Set(float64(view.DecisionsInView))
326		view.MetricsView.Phase.Set(float64(view.Phase))
327	
328		return view, view.Phase
329	}
