337	// MsgToString converts a given message to a printable string
338	func MsgToString(m *protos.Message) string {
339		if m == nil {
340			return "empty message"
341		}
342		switch m.GetContent().(type) {
343		case *protos.Message_PrePrepare:
344			return prePrepareToString(m.GetPrePrepare())
345		case *protos.Message_NewView:
346			return newViewToString(m.GetNewView())
347		case *protos.Message_ViewData:
348			return signedViewDataToString(m.GetViewData())
349		case *protos.Message_HeartBeat:
350			return heartBeatToString(m.GetHeartBeat())
351		case *protos.Message_HeartBeatResponse:
352			return heartBeatResponseToString(m.GetHeartBeatResponse())
353		default:
354			return m.String()
355		}
356	}
357	
358	func prePrepareToString(prp *protos.PrePrepare) string {
359		if prp == nil {
360			return "<empty PrePrepare>"
361		}
362		if prp.Proposal == nil {
363			return fmt.Sprintf("<PrePrepare with view: %d, seq: %d, empty proposal>", prp.View, prp.Seq)
364		}
365		return fmt.Sprintf("<PrePrepare with view: %d, seq: %d, payload of %d bytes, header: %s>",
366			prp.View, prp.Seq, len(prp.Proposal.Payload), base64.StdEncoding.EncodeToString(prp.Proposal.Header))
367	}
368	
369	func newViewToString(nv *protos.NewView) string {
370		if nv == nil || nv.SignedViewData == nil {
371			return "<empty NewView>"
372		}
373		buff := bytes.Buffer{}
374		buff.WriteString("< NewView with ")
375		for i, svd := range nv.SignedViewData {
376			buff.WriteString(signedViewDataToString(svd))
377			if i == len(nv.SignedViewData)-1 {
378				break
379			}
380			buff.WriteString(", ")
381		}
382		buff.WriteString(">")
383		return buff.String()
384	}
