543	func CommitSignaturesDigest(sigs []*protos.Signature) []byte {
544		if len(sigs) == 0 {
545			return nil
546		}
547		idb := IntDoubleBytes{}
548		for _, sig := range sigs {
549			s := IntDoubleByte{
550				A: int64(sig.Signer),
551				B: sig.Value,
552				C: sig.Msg,
553			}
554			idb.A = append(idb.A, s)
555		}
556	
557		serializedSignatures, err := asn1.Marshal(idb)
558		if err != nil {
559			panic(fmt.Sprintf("failed serializing signatures: %v", err))
560		}
561	
562		h := sha256.New()
563		h.Write(serializedSignatures)
564		return h.Sum(nil)
565	}
